pub fn config(&self, inputs: &[Input]) -> Result<Config> {
    let style_components = self.style_components()?;

    let paging_mode = match self.matches.get_one::<String>("paging").map(|s| s.as_str()) {
        Some("always") => PagingMode::Always,
        Some("never") => PagingMode::Never,
        Some("auto") | None => {
            // If we have -pp as an option when in auto mode, the pager should be disabled.
            let extra_plain = self.matches.get_count("plain") > 1;
            if extra_plain || self.matches.get_flag("no-paging") {
                PagingMode::Never
            } else if inputs.iter().any(Input::is_stdin) {
                // If we are reading from stdin, only enable paging if we write to an
                // interactive terminal and if we do not *read* from an interactive
                // terminal.
                if self.interactive_output && !std::io::stdin().is_terminal() {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            } else if self.interactive_output {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        }
        _ => unreachable!("other values for --paging are not allowed"),
    };

    let mut syntax_mapping = SyntaxMapping::new();
    // start building glob matchers for builtin mappings immediately
    // this is an appropriate approach because it's statistically likely that
    // all the custom mappings need to be checked
    syntax_mapping.start_offload_build_all();

    let extra_ignored_suffixes: Vec<&str> = self
        .matches
        .get_many::<String>("ignored-suffix")
        .unwrap_or_default();
    let layout_input = inputs
        .first()
        .expect("bat requires at least one input when building config");
    let (
        wrapping_mode,
        tab_width,
        loop_through,
        visible_line_ranges,
        highlighted_lines,
        suffixes_to_apply,
    ) = layout_input.resolve_layout(
        self.interactive_output,
        maybe_term_width,
        self.matches.get_flag("chop-long-lines"),
        self.matches.get_one::<String>("wrap").map(|s| s.as_str()),
        &style_components,
        paging_mode == PagingMode::Never,
        requested_tab_width,
        self.matches.get_flag("force-colorization"),
        self.matches.get_one::<String>("color").map(|s| s.as_str()),
        self.matches
