use clap::{Arg, ArgAction, Command};
fn main() {
    let cmd = Command::new("t")
        .arg(Arg::new("plain").short('p').long("plain").action(ArgAction::Count))
        .arg(Arg::new("paging").long("paging").action(ArgAction::Set).value_parser(["auto","never","always"]).default_value("auto"));
    for args in [vec!["t", "-pp"], vec!["t", "-pp", "--paging=always"], vec!["t", "--paging=always", "-pp"]] {
        let m = cmd.clone().get_matches_from(&args);
        println!("{:?}: paging_idx={:?} source={:?} plain_idx={:?} count={}", args, m.index_of("paging"), m.value_source("paging"), m.index_of("plain"), m.get_count("plain"));
    }
}
EOF
